const SKILL_ACTIONS=[1,2,4,5,6,7],SKILL_KEYS=['Q','E','R','T','Y','U'];
function skillBindingIndex(action){return SKILL_ACTIONS.indexOf(action)}
// Build systems: equipment, socket groups, gems and a connected passive graph.
const GEM={
 fire:{name:'灰炎弾',color:'B',kind:'active',tags:['spell','projectile'],desc:'炎の投射物を放つ',cost:12,cool:.5},
 frost:{name:'霜の環',color:'B',kind:'active',tags:['spell','area'],desc:'周囲に冷気ダメージ。移動速度を3秒間65%低下',cost:25,cool:3},
 arc:{name:'連鎖雷',color:'B',kind:'active',tags:['spell','chain'],desc:'狙った敵から最大5体へ連鎖。最初は440、次は220以内。壁で遮断',cost:20,cool:1.1},
 cleave:{name:'裂空斬',color:'R',kind:'active',tags:['attack','area'],desc:'広い扇形の強力な斬撃',cost:10,cool:.7},
 arrow:{name:'翠毒の矢',color:'G',kind:'active',tags:['attack','projectile'],desc:'矢の命中で毒を3秒付与。毎秒、矢の基礎ダメージ20%（最大5重）',cost:9,cool:.4},
 vortex:{name:'虚空渦',color:'B',kind:'active',tags:['spell','area'],desc:'狙った場所に持続する渦を作る',cost:30,cool:3.5},
 multi:{name:'多重投射',color:'G',kind:'support',tags:['projectile'],desc:'投射物 +2 / 与ダメージ 25%減 / マナ×1.3'},
 amplify:{name:'破壊増幅',color:'R',kind:'support',tags:['spell','attack'],desc:'与ダメージ 35%増 / マナ×1.4'},
 haste:{name:'迅速発動',color:'G',kind:'support',tags:['spell','attack'],desc:'クールダウン 30%短縮 / マナ×1.2'},
 area:{name:'領域拡張',color:'B',kind:'support',tags:['area'],desc:'効果範囲 45%増 / マナ×1.2'},
 leech:{name:'生命吸収',color:'R',kind:'support',tags:['spell','attack'],desc:'命中時にライフ3回復 / マナ×1.2'}
};
const MODS={life:['最大ライフ',18,42],attack:['攻撃力',3,10],spell:['魔法ダメージ %',6,18],crit:['クリティカル率 %',2,6],speed:['移動速度 %',3,9],regen:['毎秒マナ回復',1,4],guard:['ダメージ軽減 %',2,7]};
const SOCKET_COLOR_NAMES={R:'赤',G:'緑',B:'青',W:'白'};
function gemDisplayName(g){let d=GEM[g?.type];if(!d)return '未装着';if(!g.forged)return d.name;let shape=d.recipe!==undefined?d.name:({fire:'投射弾',frost:'冷却環',arc:'連鎖撃',cleave:'斬撃',arrow:'毒矢',vortex:'渦',water:'水流',wind:'風刃'}[g.type]||d.name);return g.forged.elements.map(i=>ELEMENTS[i].name).join('・')+'の'+shape;}
const COLORS={R:'#e06858',G:'#7abf8a',B:'#75b9ed',W:'#eee0b3'};
const NODES=[{id:0,x:800,y:800,kind:'root',name:'旅立ち',value:0,links:[]}];
const schools=['剣の誓い','生命の根','星の導き','刃の閃き','旅人の足','石の守り','戦の律動','血の系譜','深淵の知','鷹の瞳','風の歩み','鋼の契約'];
const types=['attack','life','spell','crit','speed','guard'];
for(let branch=0;branch<12;branch++)for(let step=1;step<=15;step++){let angle=branch*Math.PI/6+(step%3-1)*.055,radius=90+step*38,id=NODES.length,kind=types[branch%6],major=step%5===0;let node={id,x:800+Math.cos(angle)*radius,y:800+Math.sin(angle)*radius,kind,name:schools[branch]+(major?'・大節点':' '+step),value:({attack:2,life:10,spell:3,crit:1,speed:1,guard:1})[kind]*(major?3:1),links:[step===1?0:id-1],major};NODES.push(node);}
for(let b=0;b<12;b++)for(let s of [5,10,15]){let id=1+b*15+s-1,next=1+((b+1)%12)*15+s-1;NODES[id].links.push(next)}
NODES.forEach(n=>n.links.forEach(id=>{if(!NODES[id].links.includes(n.id))NODES[id].links.push(n.id)}));
let selectedGem=null,treeZoom=.65,treeFocus=0,particles=[],zonesFx=[],attackAnim=0,walkTime=0;
const terrain=new Image();terrain.src='assets/crypt.png';const knight=new Image();knight.src='assets/knight.png';
function affix(key){return GEAR_SLOTS.reduce((sum,slot)=>sum+(p?.[slot]?.mods||[]).filter(m=>m.key===key).reduce((a,m)=>a+m.value,0)+(EQUIPMENT[slot].stat===key?(p?.[slot]?.value||0):0),0)}
function passive(key){return (p?.nodes||[]).reduce((sum,id)=>sum+(NODES[id]?.kind===key?NODES[id].value:0),0)}
function stat(key){return affix(key)+passive(key)}
const baseHP=maxhp,baseDamage=damage;
maxhp=()=>baseHP()+stat('life');damage=()=>baseDamage()+stat('attack');
function rollItem(slot,rare=false){let rarity=rare?'rare':Math.random()<.65?'magic':'normal',count=rarity==='rare'?4:rarity==='magic'?2:0;let pool=Object.keys(MODS),mods=[];for(let i=0;i<count;i++){let key=pool.splice(Math.floor(Math.random()*pool.length),1)[0];mods.push({key,value:Math.round(rand(MODS[key][1],MODS[key][2])+floor*.4)})}let def=EQUIPMENT[slot],sockets=Array.from({length:Math.min(def.sockets,(rarity==='rare'?4:3)+(floor>=5?1:0)+(floor>=10?1:0))},()=>({color:['R','G','B'][Math.floor(rand(0,3))],gem:null}));return {slot,name:(rarity==='rare'?'黄昏の':rarity==='magic'?'刻印の':'鉄の')+def.base,value:Math.round(rand(def.min,def.max)+(def.stat?Math.min(10,floor*.3):floor*3)+(rare?(def.stat?2:8):0)),color:rarity==='rare'?'gold':rarity==='magic'?'blue':'',rarity,mods,sockets,links:sockets.slice(1).map(()=>Math.random()<.65)}}
function migrate(){if(!p)return;if(!p.nodes)p.nodes=[0];if(!p.stash)p.stash=[];if(!p.gems)p.gems=['fire','frost','amplify'].map(type=>({type,level:1,xp:0}));for(let slot of GEAR_SLOTS){if(!p[slot]){if(['weapon','armor'].includes(slot))p[slot]=rollItem(slot);else{p[slot]=null;continue}}let it=p[slot];if(!it.sockets){it.sockets=[{color:'W',gem:null},{color:'W',gem:null},{color:'W',gem:null}];it.links=[true,true];it.mods=[]}}for(let it of p.bag){if(!it.sockets)Object.assign(it,{sockets:[{color:'W',gem:null},{color:'W',gem:null},{color:'W',gem:null}],links:[true,true],mods:[]})}if(!p.buildVersion){p.buildVersion=2;p.weapon.sockets=[{color:'B',gem:{type:'fire',level:1,xp:0}},{color:'G',gem:{type:'multi',level:1,xp:0}},{color:'R',gem:null}];p.weapon.links=[true,true];p.armor.sockets=[{color:'B',gem:{type:'frost',level:1,xp:0}},{color:'B',gem:null},{color:'R',gem:null}];p.armor.links=[true,true];p.bindings=['fire','frost'];p.points+=3;p.gold+=120;}if(!p.bindings)p.bindings=['fire','frost'];while(p.bindings.length<6)p.bindings.push('');}
const oldNew=newGame,oldResume=resume;
newGame=type=>{oldNew(type);migrate();p.hp=maxhp();save()};resume=()=>{oldResume();if(started){migrate();p.hp=Math.min(p.hp,maxhp());save()}};
function equippedActives(){let list=[];for(let slot of GEAR_SLOTS){let it=p[slot];if(!it)continue;it.sockets.forEach((s,i)=>{if(s.gem&&GEM[s.gem.type].kind==='active')list.push({slot,index:i,gem:s.gem})})}return list}
function linkedGems(slot,index){let it=p[slot],a=index,b=index;while(a>0&&it.links[a-1])a--;while(b<it.sockets.length-1&&it.links[b])b++;return it.sockets.slice(a,b+1).map(s=>s.gem).filter(Boolean)}
function socketSupportTypes(slot,index,type){return [...new Set(linkedGems(slot,index).filter(s=>GEM[s.type].kind==='support'&&GEM[s.type].tags.some(tag=>GEM[type].tags.includes(tag))).map(s=>s.type))]}
function skillBuild(type){let active=equippedActives().find(g=>g.gem.type===type);if(!active)return null;let g=GEM[type],supports=socketSupportTypes(active.slot,active.index,type);return {type,gem:active.gem,supports,cost:g.cost*supports.reduce((v,s)=>v*(s==='amplify'?1.4:s==='multi'?1.3:1.2),1),cool:g.cool*(supports.includes('haste')?.7:1),mult:(1+(active.gem.level-1)*.12)*(supports.includes('amplify')?1.35:1)*(supports.includes('multi')?.75:1),radius:supports.includes('area')?1.45:1}}
function socketGem(slot,index){let it=p[slot];if(!GEAR_SLOTS.includes(slot)||!Number.isInteger(index)||index<0||!it?.sockets?.[index])return false;let socket=it.sockets[index],previous=socket.gem,selection=selectedGem,gems=p.gems.slice();if(selection===null){if(!previous)return false;p.gems.push(previous);socket.gem=null}else{let gem=p.gems[selection];if(!gem)return false;if(socket.color!=='W'&&socket.color!==GEM[gem.type].color){say('ソケットとジェムの色が一致しません');return false}p.gems.splice(selection,1);if(previous)p.gems.push(previous);socket.gem=gem;selectedGem=null}if(save()===false){p.gems.splice(0,p.gems.length,...gems);socket.gem=previous;selectedGem=selection;say('保存できなかったため、ジェム操作を取り消しました');return false}panel('gems');return true}
function chooseGem(i){selectedGem=selectedGem===i?null:i;panel('gems')}
function bindSkill(index,type){if(!Number.isInteger(index)||index<0||index>=SKILL_ACTIONS.length)return false;if(type&&!equippedActives().some(a=>a.gem.type===type))return false;let action=SKILL_ACTIONS[index],previous=p.bindings[index],previousCooldown=cd[action],cooldown=Math.max(0,...SKILL_ACTIONS.map((a,i)=>p.bindings[i]===type?(cd[a]||0):0));p.bindings[index]=type;cd[action]=Math.max(cd[action]||0,cooldown);if(save()===false){p.bindings[index]=previous;cd[action]=previousCooldown;say('保存できなかったため、割り当てを取り消しました');return false}panel('gems');return true}
function reroll(slot,action){let it=p[slot];if(!GEAR_SLOTS.includes(slot)||!it||!['mods','colors','links'].includes(action)||p.gold<40)return false;let previous=JSON.parse(JSON.stringify(it)),gems=p.gems.slice(),hp=p.hp;p.gold-=40;if(action==='mods')it.mods=rollItem(slot,true).mods;if(action==='colors')it.sockets.forEach(s=>{if(s.gem)p.gems.push(s.gem);s.gem=null;s.color=['R','G','B'][Math.floor(rand(0,3))]});if(action==='links')it.links=it.links.map(()=>Math.random()<.7);p.hp=Math.min(p.hp,maxhp());if(save()===false){Object.assign(it,previous);p.gems.splice(0,p.gems.length,...gems);p.hp=hp;p.gold+=40;say('保存できなかったため、再抽選を取り消しました');return false}panel('inventory');return true}
function nodeAvailable(id){return !p.nodes.includes(id)&&NODES[id].links.some(n=>p.nodes.includes(n))}
function buyNode(id){if(!Number.isInteger(id)||!NODES[id]||p.points<=0||!nodeAvailable(id))return false;p.points--;p.nodes.push(id);if(save()===false){p.points++;p.nodes.pop();say('保存できなかったため、パッシブ取得を取り消しました');return false}panel('skills');return true}
function refundTree(){let nodes=p.nodes,points=p.points,hp=p.hp;p.points+=p.nodes.filter(n=>n!==0).length;p.nodes=[0];p.hp=Math.min(p.hp,maxhp());if(save()===false){p.nodes=nodes;p.points=points;p.hp=hp;say('保存できなかったため、パッシブ返還を取り消しました');return false}panel('skills');return true}
function socketView(slot,clickable){let it=p[slot];return '<div class="sockets">'+it.sockets.map((s,i)=>(i?'<span class="link '+(it.links[i-1]?'on':'')+'">'+(it.links[i-1]?'━':'·')+'</span>':'')+'<button data-socket-slot="'+slot+'" data-socket-index="'+i+'" class="socket '+(s.gem?'filled':'')+'" style="--gem:'+COLORS[s.color]+'" aria-label="'+SOCKET_COLOR_NAMES[s.color]+'ソケット '+(i+1)+'：'+(s.gem?gemDisplayName(s.gem)+' Lv'+s.gem.level:'空き')+'" title="'+SOCKET_COLOR_NAMES[s.color]+'（'+s.color+'） / '+(s.gem?gemDisplayName(s.gem)+' Lv'+s.gem.level:'空き')+'" '+(clickable?'onclick="socketGem(\''+slot+'\','+i+')"':'onclick="panel(\'gems\')"')+'>'+(s.gem?gemIcon(s.gem.type):s.color)+'<span class="socket-color-name">'+SOCKET_COLOR_NAMES[s.color]+'</span></button>').join('')+'</div>'}
function gemIcon(type){return {fire:'◆',frost:'❄',arc:'ϟ',cleave:'⚔',arrow:'➶',vortex:'◉',multi:'⋔',amplify:'✦',haste:'»',area:'◎',leech:'♥'}[type]}
function itemDetails(it){return '<strong class="'+it.color+'">'+gearEscape(it.name)+'</strong><small>'+({rare:'レア',magic:'マジック',normal:'ノーマル'}[it.rarity]||'遺物')+' · '+gearBaseLabel(it)+' '+it.value+'</small><div class="mods">'+(it.mods||[]).map(m=>MODS[m.key][0]+' +'+m.value).join('<br>')+'</div>'}
function treeHtml(){let owned=new Set(p.nodes),edges=[];NODES.forEach(n=>n.links.forEach(id=>{if(id>n.id)edges.push('<line x1="'+n.x+'" y1="'+n.y+'" x2="'+NODES[id].x+'" y2="'+NODES[id].y+'" class="'+(owned.has(n.id)&&owned.has(id)?'learned':'')+'"/>')}));return '<div class="tree-toolbar"><span>181 ノード · 残り <b>'+p.points+'</b> ポイント · 取得 '+(p.nodes.length-1)+'</span><button onclick="zoomTree(-.15)">−</button><button onclick="zoomTree(.15)">＋</button><button onclick="refundTree()">全返還（無料）</button></div><p class="muted">金のノードが取得済み、明るい枠が取得可能。ノードを選ぶと詳細が表示されます。スクロールで全体を探索できます。</p><div id="treeViewport"><svg id="tree" width="'+1600*treeZoom+'" height="'+1600*treeZoom+'" viewBox="0 0 1600 1600">'+edges.join('')+NODES.map(n=>'<g role="button" tabindex="0" aria-label="'+n.name+'" onclick="inspectNode('+n.id+')" onkeydown="if(event.key===\'Enter\')inspectNode('+n.id+')" class="node '+(owned.has(n.id)?'owned':nodeAvailable(n.id)?'available':'locked')+'"><circle cx="'+n.x+'" cy="'+n.y+'" r="'+(n.id===0?28:n.major?17:10)+'"/><text x="'+n.x+'" y="'+(n.y+5)+'">'+(n.id===0?'✦':n.major?'◆':'')+'</text><title>'+n.name+' '+(MODS[n.kind]?.[0]||'')+' +'+n.value+'</title></g>').join('')+'</svg></div><div id="nodeDetail"></div>'}
function inspectNode(id){treeFocus=id;let n=NODES[id];$('nodeDetail').innerHTML='<b>'+n.name+'</b>　'+(MODS[n.kind]?.[0]||'開始地点')+(n.value?' +'+n.value:'')+' <button onclick="buyNode('+id+')" '+(!nodeAvailable(id)||!p.points?'disabled':'')+'>'+(p.nodes.includes(id)?'取得済み':'1ポイントで取得')+'</button>'}
function zoomTree(amount){let vp=$('treeViewport'),cx=(vp.scrollLeft+vp.clientWidth/2)/treeZoom,cy=(vp.scrollTop+vp.clientHeight/2)/treeZoom;treeZoom=clamp(treeZoom+amount,.4,1.5);$('tree').setAttribute('width',1600*treeZoom);$('tree').setAttribute('height',1600*treeZoom);vp.scrollLeft=cx*treeZoom-vp.clientWidth/2;vp.scrollTop=cy*treeZoom-vp.clientHeight/2}
const legacyPanel=panel;
panel=kind=>{if(!started||dead)return;migrate();$('card').classList.toggle('wide',['skills','gems','inventory'].includes(kind));if(!['skills','gems','inventory'].includes(kind)){legacyPanel(kind);if(kind==='help')$('card').innerHTML+='<p>G：ジェムとソケット。Q/Eの技は装着したアクティブジェムから割り当てます。リンクされたサポートジェムだけが技に作用します。</p>';return}paused=true;held=false;keys={};$('modal').classList.remove('hidden');let h='<button class="close" onclick="closePanel()">閉じる ×</button><label>ASHEN DEPTHS / BUILD YOUR LEGACY</label><nav class="tabs"><button onclick="panel(\'inventory\')">装備・鍛造 I</button><button onclick="panel(\'gems\')">スキルジェム G</button><button onclick="panel(\'skills\')">パッシブツリー P</button><button onclick="panel(\'stash\')">倉庫</button></nav>';
if(kind==='skills'){h+='<h2>魂の星図</h2>'+treeHtml();$('card').innerHTML=h;inspectNode(treeFocus);let vp=$('treeViewport');vp.scrollLeft=800*treeZoom-vp.clientWidth/2;vp.scrollTop=800*treeZoom-vp.clientHeight/2;save();return}
if(kind==='inventory')h+=gearInventoryHtml();
if(kind==='gems'){h+='<h2>共鳴する宝石</h2><button class="socket-help-toggle" aria-expanded="false" onclick="toggleSocketHelp(this)">色・リンクの使い方</button><section id="socketHelp" hidden class="socket-guide" aria-label="ジェムの色とリンクの説明"><h3>R・G・Bは「入れられるジェムの色」</h3><p><b>R＝赤　G＝緑　B＝青　W＝白（どの色でもOK）</b><br>色自体に攻撃力などの効果はありません。入れたジェムがスキルや強化効果を決めます。</p><p><b>━ はリンク、· は未接続。</b>つながった範囲の対応スキルにサポートが効きます。例：青の「灰炎弾」と緑の「多重投射」をリンクすると、火の玉が増えます。</p><p>①左でジェムを選ぶ → ②右の「このジェムを装着する」 → ③同色か白の穴で決定 → ④左のスキル枠から割り当て。サポートは枠への割り当て不要です。<br>Bで一覧に戻り、もう一度Bでジェム選択を取消。未選択で装着済みの穴を押すと取り外せます。色再抽選では、装着ジェムは手持ちへ戻ります。</p></section><div class="equipment">';for(let slot of GEAR_SLOTS)if(p[slot]?.sockets.length)h+='<div class="gearcard"><h3>'+gearEscape(p[slot].name)+'</h3>'+socketView(slot,true)+socketEffectHtml(slot)+'<small>━ でつながった範囲にサポート効果が適用</small></div>';h+='</div><div class="bindings">';for(let i=0;i<6;i++){let b=skillBuild(p.bindings[i]);h+='<label>'+SKILL_KEYS[i]+' <select aria-label="スキル枠 '+(i+1)+' / '+SKILL_KEYS[i]+'" onchange="bindSkill('+i+',this.value)"><option value="">未割当</option>'+equippedActives().map(a=>'<option value="'+a.gem.type+'" '+(p.bindings[i]===a.gem.type?'selected':'')+'>'+gemDisplayName(a.gem)+'</option>').join('')+'</select></label><p>'+(b?Math.ceil(b.cost)+'マナ / '+b.cool.toFixed(2)+'秒 / '+(b.supports.map(s=>GEM[s].name).join('・')||'サポートなし'):'アクティブジェムを装着してください')+'</p>'}h+='</div><div class="gemgrid">';p.gems.forEach((g,i)=>{let d=GEM[g.type];h+='<button class="gemcard '+(selectedGem===i?'selected':'')+'" onclick="chooseGem('+i+')" style="--gem:'+COLORS[d.color]+'"><i>'+gemIcon(g.type)+'</i><b>'+gemDisplayName(g)+'</b><small>'+d.color+' / '+(d.kind==='active'?'アクティブ':'サポート')+' / Lv '+g.level+'</small><small>'+(g.forged?'原型：'+d.name+'。属性は抽選結果に置き換わります。':d.desc)+'</small><small>経験値 '+g.xp+' / '+g.level*80+'</small></button>'});h+='</div>'}
$('card').innerHTML=h;save()};
addEventListener('keydown',e=>{if(e.key.toLowerCase()==='g'&&!e.repeat)panel('gems')});
const priorHit=hit;
hit=(e,d)=>{if(e.hp<=0)return;let before=drops.length,alive=e.hp>0;let critical=!e.dotTick&&Math.random()<Math.min(.6,.05+stat('crit')/100);priorHit(e,d*(critical?1.65:1));if(critical&&texts.length)texts[texts.length-1].c='#fff1b5';if(alive&&e.hp<=0){for(let i=before;i<drops.length;i++)drops[i].item=rollItem(randomGearSlot(),e.boss);for(let slot of GEAR_SLOTS)for(let s of p[slot]?.sockets||[])if(s.gem){s.gem.xp+=10;while(s.gem.level<20&&s.gem.xp>=s.gem.level*80){s.gem.xp-=s.gem.level*80;s.gem.level++}}if(Math.random()<.13){let types=Object.keys(GEM);p.gems.push({type:types[Math.floor(rand(0,types.length))],level:1,xp:0});feed('スキルジェムを獲得 · G')}save()}};
const oldHurt=hurt;hurt=d=>oldHurt(d*(1-Math.min(.65,stat('guard')/100)));
function chainTargets(origin,aim,pool,limit=5){let remaining=pool.filter(e=>e.hp>0),first=remaining.filter(e=>dist(origin,e)<=440&&lineClear(origin,e)).sort((a,b)=>dist(a,aim)-dist(b,aim)||dist(a,origin)-dist(b,origin))[0];if(!first||limit<1)return[];let result=[first],from=first;while(result.length<limit){let next=remaining.filter(e=>!result.includes(e)&&dist(from,e)<=220&&lineClear(from,e)).sort((a,b)=>dist(a,from)-dist(b,from))[0];if(!next)break;result.push(next);from=next}return result}
function spellHit(e,d,b){hit(e,d);if(b.supports.includes('leech'))p.hp=Math.min(maxhp(),p.hp+3)}
const oldCast=cast;
cast=n=>{if(n===0||n===3){if(!paused&&cd[n]<=0)attackAnim=.28;oldCast(n);return}if(paused||dead||cd[n]>0)return;migrate();let b=skillBuild(p.bindings[skillBindingIndex(n)]);if(!b){say('G でアクティブジェムを装着・割当してください');return}if(p.mp<b.cost){say('マナが足りない');return}p.mp-=b.cost;cd[n]=b.cool;SKILL_ACTIONS.forEach((action,i)=>{if(p.bindings[i]===b.type)cd[action]=b.cool});attackAnim=.35;let def=GEM[b.type],d=damage()*b.mult*(def.tags.includes('spell')?1.3+p.focus*.15+stat('spell')/100:1.2),a=Math.atan2(mouse.y-H/2,mouse.x-W/2);if(def.recipe!==undefined){castCraftedSkill(b,d,a);return}if(def.tags.includes('projectile')){let count=b.supports.includes('multi')?3:1;for(let j=0;j<count;j++){let angle=a+(j-(count-1)/2)*.22;shots.push({x:p.x,y:p.y,vx:Math.cos(angle)*560,vy:Math.sin(angle)*560,life:1.7,damage:d,skill:b.type,elements:b.elements,enemy:false,tint:b.elements?.length?ELEMENTS[b.elements[0]].color:b.type==='arrow'?'#80df91':'#ffad59',leech:b.supports.includes('leech')})}emit(p.x,p.y,12,b.type==='arrow'?'#78ce8e':'#ffb352')}
if(b.type==='frost'||b.type==='cleave'||b.type==='wind'){let r=(b.type==='wind'?210:b.type==='frost'?190:145)*b.radius;burst(p.x,p.y,r,b.type==='frost'?'#8cdce7':'#f3cb8a');emit(p.x,p.y,50,b.type==='frost'?'#9beafa':'#eec67d');for(let e of enemies){let angle=Math.atan2(e.y-p.y,e.x-p.x);if(dist(e,p)<r&&(b.type==='frost'||b.type==='wind'||Math.cos(angle-a)>.1)){spellHit(e,d*1.5,b);if(b.type==='frost')e.slow=3}}}
if(b.type==='arc'){let from={x:p.x,y:p.y},targets=chainTargets(p,{x:p.x+mouse.x-W/2,y:p.y+mouse.y-H/2},enemies);for(let e of targets){zonesFx.push({kind:'bolt',x:from.x,y:from.y,tx:e.x,ty:e.y,life:.3,max:.3});spellHit(e,d,b);emit(e.x,e.y,10,'#a9bfff');from=e}}
if(b.type==='vortex'){let distance=Math.min(330,Math.hypot(mouse.x-W/2,mouse.y-H/2));zonesFx.push({kind:'vortex',x:p.x+Math.cos(a)*distance,y:p.y+Math.sin(a)*distance,r:100*b.radius,life:3,max:3,tick:0,damage:d*.45,build:b})}};
function emit(x,y,count,color){for(let i=0;i<count;i++){let a=rand(0,Math.PI*2),s=rand(30,190);particles.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life:rand(.3,.8),color})}if(particles.length>450)particles.splice(0,particles.length-450)}
const priorBurst=burst;burst=(x,y,r,color)=>{priorBurst(x,y,r,color);emit(x,y,Math.min(35,r/3),color)};
const priorUpdate=update;
update=dt=>{let running=!paused&&started,ox=p?.x||0,oy=p?.y||0;priorUpdate(dt);if(!running||paused)return;let speed=1+Math.min(.8,stat('speed')/100);p.x=clamp(ox+(p.x-ox)*speed,-1140,1140);p.y=clamp(oy+(p.y-oy)*speed,-1140,1140);if(p.x!==ox||p.y!==oy)walkTime+=dt*12;attackAnim=Math.max(0,attackAnim-dt);p.mp=Math.min(100,p.mp+stat('regen')*dt);for(let s of shots)if(!s.enemy){if(Math.random()<.5)emit(s.x,s.y,1,s.tint||'#ffb455');}particles.forEach(a=>{a.x+=a.vx*dt;a.y+=a.vy*dt;a.vx*=.96;a.vy*=.96;a.life-=dt});particles=particles.filter(a=>a.life>0);for(let z of zonesFx){z.life-=dt;if(z.kind==='vortex'){z.tick-=dt;if(z.tick<=0){z.tick=.4;for(let e of enemies)if(dist(z,e)<z.r)spellHit(e,z.damage,z.build);emit(z.x,z.y,5,'#b397e9')}}}zonesFx=zonesFx.filter(z=>z.life>0)};
function drawGround(){if(terrain.complete&&terrain.naturalWidth)ctx.drawImage(terrain,-1200,-1200,2400,2400)}
function drawKnight(){if(!knight.complete||!knight.naturalWidth)return false;let bob=Math.sin(walkTime)*2,swing=attackAnim>0?Math.sin(attackAnim*22)*.12:0;ctx.save();ctx.translate(p.x,p.y+bob-18);ctx.rotate(swing);ctx.globalAlpha=p.inv>0?.72:1;ctx.scale(mouse.x<W/2?-1:1,1);ctx.drawImage(knight,-38,-50,76,96);ctx.restore();return true}
function drawExtra(){ctx.save();ctx.translate(W/2-(p?.x||0),H/2-(p?.y||0));ctx.globalCompositeOperation='lighter';for(let z of zonesFx){ctx.globalAlpha=Math.min(1,z.life*3);ctx.strokeStyle=z.kind==='bolt'?'#c2d7ff':'#8f68dc';ctx.lineWidth=2;if(z.kind==='bolt'){ctx.beginPath();ctx.moveTo(z.x,z.y);for(let j=1;j<=6;j++){let t=j/6;ctx.lineTo(z.x+(z.tx-z.x)*t+(j<6?Math.sin(j*43+clock*30)*13:0),z.y+(z.ty-z.y)*t)}ctx.stroke()}else for(let j=0;j<4;j++){ctx.beginPath();ctx.ellipse(z.x,z.y,z.r*(.4+j*.18),z.r*(.25+j*.12),clock*(j%2?1:-1)+j,0,6.28);ctx.stroke()}}for(let a of particles){ctx.globalAlpha=Math.min(1,a.life*2);circle(a.x,a.y,2,a.color)}ctx.restore();if(p){let buttons=document.querySelectorAll('.actions button strong');for(let i=0;i<2;i++){let b=skillBuild(p.bindings?.[i]);buttons[i+1].textContent=b?gemDisplayName(b.gem):'未装着';$('cd'+(i+1)).textContent=b?(cd[i+1]>0?cd[i+1].toFixed(1)+' s':Math.ceil(b.cost)+' MANA'):'G で設定'}}}
const priorDraw=draw;draw=()=>{priorDraw();drawExtra()};
const oldFloor=enterFloor;enterFloor=()=>{zonesFx=[];particles=[];oldFloor()};
const nav=document.querySelector('.menu');nav.insertAdjacentHTML('afterbegin','<button onclick="panel(\'gems\')">ジェム G</button>');

const revenant=new Image();revenant.src='assets/revenant.png';
function drawEnemy(e){if(!revenant.complete||!revenant.naturalWidth)return false;let size=e.boss?110:64,bob=Math.sin(clock*5+e.x)*2;ctx.save();ctx.translate(e.x,e.y-14+bob);ctx.scale(e.x>p.x?-1:1,1);ctx.rotate(Math.sin(clock*4+e.y)*.035);ctx.filter=e.slow?'sepia(.3) hue-rotate(140deg) saturate(1.4)':e.kind?'sepia(.4) hue-rotate(245deg)':'none';ctx.drawImage(revenant,-size*.5,-size*.65,size,size);ctx.restore();return true}

// Explain the exact linked support rules used by skillBuild, including duplicate actives.
function socketEffectRows(slot){let sockets=p[slot]?.sockets||[],actives=equippedActives();return sockets.flatMap((socket,index)=>{let gem=socket.gem;if(!gem)return [];let def=GEM[gem.type];if(def.kind==='active'){let source=actives.find(a=>a.gem.type===gem.type),primary=source.slot===slot&&source.index===index,bindings=p.bindings.flatMap((type,i)=>type===gem.type?[i+1]:[]);return [{index,type:gem.type,kind:'active',primary,bindings,supports:socketSupportTypes(slot,index,gem.type)}]}let targets=actives.filter(a=>a.slot===slot&&linkedGems(slot,a.index).includes(gem)&&socketSupportTypes(slot,a.index,a.gem.type).includes(gem.type)).map(a=>a.gem.type);return [{index,type:gem.type,kind:'support',targets:[...new Set(targets)]}]})}
function socketEffectHtml(slot){return '<div class="socket-effects">'+socketEffectRows(slot).map(row=>{let name=gemDisplayName(p[slot].sockets[row.index].gem);if(row.kind==='support')return '<p hidden data-effect-index="'+row.index+'"><b>'+name+'</b><br>'+(row.targets.length?'対応先：'+row.targets.map(t=>GEM[t].name).join('・'):'効果なし：同じリンク内に対応スキルがありません')+'</p>';return '<p hidden data-effect-index="'+row.index+'"><b>'+name+'</b> · 穴 '+(row.index+1)+'<br>'+(row.primary?(row.bindings.length?'使用枠：'+row.bindings.join('・'):'未割当：左のスキル枠から設定してください'):'同じスキルが別の穴にもあります。この穴は現在の発動元ではありません')+'<br>リンク強化：'+(row.supports.map(t=>GEM[t].name).join('・')||'なし')+'</p>'}).join('')+'</div>'}

function toggleSocketHelp(button){let help=$('socketHelp');help.hidden=!help.hidden;button.setAttribute('aria-expanded',String(!help.hidden));button.textContent=help.hidden?'色・リンクの使い方':'使い方を閉じる'}
addEventListener('focusin',e=>{let socket=e.target.closest?.('[data-socket-slot]');document.querySelectorAll('[data-effect-index]').forEach(row=>{row.hidden=!(socket&&row.closest('.gearcard')===socket.closest('.gearcard')&&row.dataset.effectIndex===socket.dataset.socketIndex)})});
